function fx(style,x=p.x,y=p.y,color=role().color,life=.65,angle=face){effects.push({style,x,y,color,life,total:life,angle});}

function drawEffects(){for(const e of effects){const a=screen(e.x,e.y),t=1-e.life/e.total,color=e.color;ctx.save();ctx.globalAlpha=Math.min(1,e.life/e.total*1.7);ctx.translate(a.x,a.y);ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=3;
if(['spin','ground','aura','heal','poison','fire','dark','impact','cast','smoke'].includes(e.style)){const r=15+t*(e.style==='spin'?165:e.style==='ground'?140:e.style==='poison'?155:80);ellipse(0,-5,r,r*.55,color+'25');ctx.beginPath();ctx.ellipse(0,-5,r,r*.55,t*2,0,Math.PI*2);ctx.stroke();for(let j=0;j<8;j++){const b=j*Math.PI/4+t*4,x=Math.cos(b)*r,y=Math.sin(b)*r*.5;if(e.style==='heal'){line(x,y-15,x,y-25,color,2);line(x-4,y-20,x+4,y-20,color,2);}else if(e.style==='fire'){polygon([[x-5,y],[x+Math.sin(j+t*10)*5,y-25-t*20],[x+6,y]],'#f7bb6c');}else ellipse(x,y-10,3+t*3,3+t*4,color);}}
else if(e.style==='lightning'){ctx.lineWidth=4;ctx.shadowColor=color;ctx.shadowBlur=15;const pts=[[0,-180],[-18,-130],[12,-134],[-8,-80],[16,-86],[0,-10]];ctx.beginPath();pts.forEach(([x,y],i)=>i?ctx.lineTo(x+Math.sin(t*15+i)*8,y):ctx.moveTo(x,y));ctx.stroke();ellipse(0,0,28+t*40,12+t*20,color+'44');}
else if(['slash','cross','fan'].includes(e.style)){const r=35+t*45;ctx.lineWidth=5;ctx.beginPath();for(let i=0;i<=18;i++){const angle=e.angle-.95+i/18*1.9,px=Math.cos(angle)*r,py=Math.sin(angle)*r*.62-16;i?ctx.lineTo(px,py):ctx.moveTo(px,py);}ctx.stroke();if(e.style==='cross'){const ux=Math.cos(e.angle),uy=Math.sin(e.angle)*.62;line(ux*25-uy*15,uy*25-16+ux*15,ux*65+uy*15,uy*65-16-ux*15,color,3);}}
else if(['beam','finger','dragon','dash'].includes(e.style)){const length=e.style==='dragon'?260:e.style==='beam'?280:e.style==='dash'?180:120,ux=Math.cos(e.angle),uy=Math.sin(e.angle)*.62;line(0,-20,ux*length*t,uy*length*t-20,color,e.style==='finger'?20:8);for(let j=0;j<8;j++){const d=(j/8+t*.15)*length,off=Math.sin(j+t*13)*18;ellipse(ux*d+off,uy*d-20+Math.cos(j+t*8)*14,15+(e.style==='dragon'?10:0),9,color+'88');}if(e.style==='dragon'){const x=ux*length*t,y=uy*length*t-20;polygon([[x-18,y],[x+ux*30,y+uy*30-8],[x+10,y+12],[x,y+20]],'#e8bc81');line(x-5,y-10,x-16,y-35,color,4);line(x+6,y-10,x+18,y-30,color,4);}}
ctx.restore();}for(const b of shots){if(b.opts.delay>0)continue;const a=screen(b.x,b.y),target=b.target?screen(b.target.x,b.target.y-15):screen(b.x+b.vx*40,b.y+b.vy*40),angle=Math.atan2(target.y-a.y,target.x-a.x);ctx.save();ctx.translate(a.x,a.y);ctx.rotate(angle);if(b.style==='arrow'||b.style.includes('Arrow')){line(-20,0,6,0,b.style==='fireArrow'?'#f6b06a':b.style==='poisonArrow'?'#a6d77b':'#e7d7aa',2);polygon([[10,0],[1,-4],[1,4]],'#e8dfc0');}else if(b.style==='talisman'){polygon([[-8,-11],[7,-11],[8,10],[-7,10]],'#f1d6a1');line(-3,-6,3,5,'#a25043',2);}else{ellipse(0,0,b.style==='darkOrb'?16:8,b.style==='darkOrb'?13:6,b.color+'66');ellipse(0,0,b.style==='darkOrb'?9:5,b.style==='darkOrb'?8:4,b.color);line(-30,0,-5,0,b.color+'66',4);}ctx.restore();}}
